#!/usr/bin/env node
/**
 * Builds the signed, release-ready Android APK.
 *
 * The `android/` folder is generated by `expo prebuild` and is not committed, so
 * the release signing config is applied here on every build instead of being
 * hand-edited into a generated file. The keystore itself never lives in the
 * repository: its path and passwords are read from Gradle properties in
 * ~/.gradle/gradle.properties.
 *
 *   node scripts/build-android-release.mjs            # prebuild + assembleRelease
 *   node scripts/build-android-release.mjs --skip-prebuild
 */
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { copyFileSync, existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const androidDir = path.join(root, 'android');
const appGradlePath = path.join(androidDir, 'app', 'build.gradle');
const requiredProperties = [
  'MUNDAIQ_UPLOAD_STORE_FILE',
  'MUNDAIQ_UPLOAD_KEY_ALIAS',
  'MUNDAIQ_UPLOAD_STORE_PASSWORD',
  'MUNDAIQ_UPLOAD_KEY_PASSWORD',
];

function fail(message) {
  console.error(`\n✖ ${message}\n`);
  process.exit(1);
}

function run(command, cwd) {
  console.log(`\n▸ ${command}\n`);
  const result = spawnSync(command, { cwd, shell: true, stdio: 'inherit' });
  if (result.status !== 0) fail(`Command failed (${result.status}): ${command}`);
}

function checkSigningProperties() {
  const propertiesFile = path.join(homedir(), '.gradle', 'gradle.properties');
  const contents = existsSync(propertiesFile) ? readFileSync(propertiesFile, 'utf8') : '';
  const missing = requiredProperties.filter((key) => !new RegExp(`^${key}=.+`, 'm').test(contents));
  if (missing.length > 0) {
    fail(
      `Missing signing properties in ${propertiesFile}:\n  ${missing.join('\n  ')}\n\n` +
        'See docs/github-releases.md ("Signing key") for the expected format.',
    );
  }
}

/** Idempotently adds the release signing config to the generated build.gradle. */
function patchGradleSigning() {
  let gradle = readFileSync(appGradlePath, 'utf8');
  if (gradle.includes('MUNDAIQ_UPLOAD_STORE_FILE')) {
    console.log('▸ Release signing already configured in android/app/build.gradle');
    return;
  }

  const debugConfig = `        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
`;
  const withRelease = `        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        release {
            if (project.hasProperty('MUNDAIQ_UPLOAD_STORE_FILE')) {
                storeFile file(MUNDAIQ_UPLOAD_STORE_FILE)
                storePassword MUNDAIQ_UPLOAD_STORE_PASSWORD
                keyAlias MUNDAIQ_UPLOAD_KEY_ALIAS
                keyPassword MUNDAIQ_UPLOAD_KEY_PASSWORD
            }
        }
    }
`;
  if (!gradle.includes(debugConfig)) {
    fail('android/app/build.gradle did not match the expected Expo template; signing not applied.');
  }
  gradle = gradle.replace(debugConfig, withRelease);

  const releaseBuildType = `        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug`;
  const signedRelease = `        release {
            signingConfig signingConfigs.release`;
  if (!gradle.includes(releaseBuildType)) {
    fail('Release build type in android/app/build.gradle did not match; signing not applied.');
  }
  gradle = gradle.replace(releaseBuildType, signedRelease);

  writeFileSync(appGradlePath, gradle);
  console.log('▸ Applied release signing config to android/app/build.gradle');
}

const skipPrebuild = process.argv.includes('--skip-prebuild');
const appConfig = JSON.parse(readFileSync(path.join(root, 'app.json'), 'utf8')).expo;
const version = appConfig.version;

checkSigningProperties();

if (!skipPrebuild) {
  run('npx expo prebuild --platform android --no-install', root);
}

patchGradleSigning();
// This machine has 2 CPU cores / 7.7 GB RAM. A single 64-bit ABI with serial
// Gradle workers keeps clang from exhausting memory during native builds.
run(
  'gradlew.bat assembleRelease --no-daemon --no-parallel --max-workers=1 -PreactNativeArchitectures=arm64-v8a',
  androidDir,
);

const builtApk = path.join(androidDir, 'app', 'build', 'outputs', 'apk', 'release', 'app-release.apk');
if (!existsSync(builtApk)) fail(`Build finished but no APK was found at ${builtApk}`);

const releaseDir = path.join(root, 'release');
mkdirSync(releaseDir, { recursive: true });
const apkName = `MundaIQ-${version}.apk`;
const apkPath = path.join(releaseDir, apkName);
copyFileSync(builtApk, apkPath);

const sha256 = createHash('sha256').update(readFileSync(apkPath)).digest('hex');
const sizeMb = (statSync(apkPath).size / (1024 * 1024)).toFixed(2);
writeFileSync(path.join(releaseDir, `MundaIQ-${version}.apk.sha256`), `${sha256}  ${apkName}\n`);

console.log(`\n✔ Release APK ready`);
console.log(`  File   : release/${apkName}`);
console.log(`  Size   : ${sizeMb} MB`);
console.log(`  SHA-256: ${sha256}\n`);
